// FlowsSendEmailInput is the request body of [FlowsService.SendEmail].
type FlowsSendEmailInput struct {
	// Id of the flow to add the step to. Must be `draft`/`template` or paused (`closed`); an active
	// flow must be paused first (`flows_close`) — ask the user.
	FlowID string `json:"flowId"`
	// Email subject line. Supports {name}/{email}/{telephone} personalization tokens.
	Subject string `json:"subject"`
	// `html` (default): renders inside the standard branded template from the slot fields. `text`:
	// plain text, uses `content` instead, no template.
	Format *FlowsSendEmailInputFormat `json:"format,omitzero"`
	// Template copy locale for placeholder fallbacks. Defaults to pt-BR.
	Locale *FlowsSendEmailInputLocale `json:"locale,omitzero"`
	// Small uppercase label above the title, e.g. "TUDO PRONTO!". `format: html` only.
	Eyebrow *string `json:"eyebrow,omitzero"`
	// Email heading (H1) inside the template. `format: html` only.
	Title *string `json:"title,omitzero"`
	// Heading introducing the main message, shown below the illustration. `format: html` only.
	Subtitle *string `json:"subtitle,omitzero"`
	// Main paragraph text under `subtitle` (plain text, no HTML tags — the template supplies the
	// styling). `format: html` only, but effectively required for it.
	Body *string `json:"body,omitzero"`
	// Heading of the benefits card, e.g. "O que você encontra por aqui". `format: html` only.
	BenefitsTitle *string `json:"benefitsTitle,omitzero"`
	// Checklist items inside the benefits card, each rendered with a check icon. Defaults to 3
	// placeholder items. `format: html` only.
	Benefits []string `json:"benefits,omitzero"`
	// CTA button label. `format: html` only.
	CtaLabel *string `json:"ctaLabel,omitzero"`
	// CTA button link — a real URL, or a checkout token ({checkout} / {checkout:offerId}). `format:
	// html` only.
	CtaHref *string `json:"ctaHref,omitzero"`
	// Small text under the CTA button, e.g. a fallback instruction. `format: html` only.
	CtaNote *string `json:"ctaNote,omitzero"`
	// Small print at the very bottom of the email (e.g. company address). `format: html` only. OMIT
	// IT: the tool fills this with the sender's own business name + registered address (account
	// profile), which is what an email needs at the bottom. Pass a value only when the user dictates
	// different small print — and never invent an address.
	FooterNote *string `json:"footerNote,omitzero"`
	// Absolute https URL of the logo shown at the TOP of the email. `format: html` only. OMIT IT: the
	// tool resolves the workspace brand logo, then the user's profile photo, and falls back to writing
	// the sender's name as text. Pass a value only when the user points at a specific image (e.g. one
	// they just uploaded); a relative path or a `data:` URI is rejected (a sent email has no page
	// origin, and inline images are stripped by Gmail/Outlook).
	LogoURL *string `json:"logoUrl,omitzero"`
	// CSS font-family stack for the whole email (e.g. "Georgia, serif"). Default Arial/Helvetica.
	// `format: html` only.
	FontFamily *string `json:"fontFamily,omitzero"`
	// CTA button background color (hex). Default `#D4FF00`. `format: html` only.
	AccentColor *string `json:"accentColor,omitzero"`
	// CTA button text color (hex). Default `#000000`. `format: html` only.
	ButtonTextColor *string `json:"buttonTextColor,omitzero"`
	// Title (H1) text color (hex). Default `#1F2123`. `format: html` only.
	TitleColor *string `json:"titleColor,omitzero"`
	// Subtitle + body paragraph text color (hex). Default `#363940`. `format: html` only.
	TextColor *string `json:"textColor,omitzero"`
	// Footer note text color (hex). Default `#697077`. `format: html` only.
	FooterTextColor *string `json:"footerTextColor,omitzero"`
	// Email wrapper background (hex or CSS gradient). Defaults to the standard neutral backdrop
	// (`#F4F5F5`). `format: html` only.
	CardBackground *string `json:"cardBackground,omitzero"`
	// Card max-width in px. Default `640`. `format: html` only.
	ContentWidthPx *float64 `json:"contentWidthPx,omitzero"`
	// Plain text body. Required when `format: text`; ignored for `format: html` (use the slot fields,
	// or `customHtml`, instead). Personalization tokens: {name}/{email}/{telephone},
	// {checkout}/{checkout:offerId}.
	Content *string `json:"content,omitzero"`
	// A complete, self-contained, email-safe HTML body — `format: html` only, and REPLACES the slot
	// fields entirely when present. Use this to actually reproduce a chosen design (the slot-only mode
	// can only recolor the fixed skeleton). Any `<style>` block / `var(--...)` left in is auto-inlined
	// server-side before sending (safety net, not a license to skip inline styles), but layout is NOT
	// rewritten — flexbox/grid still silently break in real inboxes. See the clickmax-flows skill
	// email-authoring reference for the authoring rules (table layout, inline styles only, one CTA).
	CustomHTML *string `json:"customHtml,omitzero"`
	// Verified sender signature id (EmailSenderSignatures). Resolve one with
	// `email_sender_signatures_list` (pick `confirmed: true`) and pass it whenever one exists; never
	// fabricate a uuid. Omit ONLY when the workspace has no confirmed signature at all — the node
	// saves fine, but sending will fail (fatal at hermes message creation, not caught by activation)
	// until a signature is added. When you omit it, you MUST tell the user in your reply that they
	// have no sender email configured yet and the message will not send until they add and verify one.
	EmailSenderSignatureID *string `json:"emailSenderSignatureId,omitzero"`
	// Id of the next step this message's main output goes to. Optional. Does not connect anything INTO
	// this message — use `after` for that.
	Target *string `json:"target,omitzero"`
	// Inserts this message after that step, preserving its previous destination: the step's output now
	// points to this message, and whatever it pointed to before becomes this message's next step. The
	// way to add a message without leaving it orphan (and to insert in the middle of a chain). Timing
	// follows the anchor: `after` another message sends both at the same moment — to send N hours
	// later, anchor on the delay that holds that wait (`{step: <delay id>, handle: 'continue'}`).
	After *FlowsSendEmailInputAfter `json:"after,omitzero"`
}

